CREATE TABLE ad_packages (id serial PRIMARY KEY, name text NOT NULL, description text NOT NULL, channel text NOT NULL CHECK(channel IN ('website','sosial','gabungan')), price bigint NOT NULL CHECK(price>=0), duration_days int NOT NULL CHECK(duration_days>0), features jsonb NOT NULL DEFAULT '[]', active boolean NOT NULL DEFAULT true, sort_order int NOT NULL DEFAULT 0);
CREATE TABLE ad_requests (id serial PRIMARY KEY, token text NOT NULL UNIQUE, name text NOT NULL, whatsapp text NOT NULL, kind text NOT NULL CHECK(kind IN ('properti','usaha')), type_id int REFERENCES property_types(id), package_id int NOT NULL REFERENCES ad_packages(id), location text NOT NULL, description text NOT NULL, photo_url text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'baru' CHECK(status IN ('baru','dihubungi','deal','ditolak')), notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE survey_requests (id serial PRIMARY KEY, token text NOT NULL UNIQUE, property_id int NOT NULL REFERENCES properties(id), name text NOT NULL, whatsapp text NOT NULL, preferred_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'baru' CHECK(status IN ('baru','dihubungi','deal','ditolak')), notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE lead_events (id bigserial PRIMARY KEY, property_id int REFERENCES properties(id), event_type text NOT NULL CHECK(event_type IN ('whatsapp_click','ad_request_submitted','survey_request_submitted','filter_used')), page text NOT NULL, source text NOT NULL DEFAULT '', utm_source text NOT NULL DEFAULT '', utm_medium text NOT NULL DEFAULT '', utm_campaign text NOT NULL DEFAULT '', utm_term text NOT NULL DEFAULT '', utm_content text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX lead_events_date ON lead_events(created_at);
CREATE TABLE site_settings (key text PRIMARY KEY, value text NOT NULL);
CREATE TABLE content_pages (slug text PRIMARY KEY, title text NOT NULL, body text NOT NULL);
